double idle_cost;

double de_step = (dt > 0) ? (raw_le * p->energy_scale / dt) : 0.0;
if (dt > 0 && bat + 2.7 * dt < 99.5 && bat - de_step * dt > p->bat_floor + 1.0) {
    /* Safe fast O(1) leg update: guaranteed never to cap at 100 or drop below bat_floor */
    bat += (p->cum_net_solar[t + dt] - p->cum_net_solar[t]) - de_step * dt;
    t += dt;
    if (bat < min_bat) min_bat = bat;
} else {
    for (int s = 0; s < dt; s++) {
        /* If next drive step would breach bat_floor, insert solar wait ticks */
        while (t + dt - s + 1 <= max_t) {
            double b_try = bat + p->solar_gain[t + 1];
            if (b_try > 100.0) b_try = 100.0;
            b_try -= p->idle_cost + de_step;
            if (b_try >= p->bat_floor) break;
            /* Wait 1 tick */
            double net_w = p->solar_gain[t + 1] - p->idle_cost;
            if (net_w <= 0.01) break;
            t++;
            bat += p->solar_gain[t];
            if (bat > 100.0) bat = 100.0;
            bat -= p->idle_cost;
            if (bat < min_bat) min_bat = bat;
        }
        if (t + 1 > max_t) return -1e18;
        t++;
        bat += p->solar_gain[t];
        if (bat > 100.0) bat = 100.0;
        bat -= p->idle_cost + de_step;
        if (bat < min_bat) min_bat = bat;
        if (bat < p->bat_floor) return -1e18;
    }
}

